// "Kutipan hari ini": lima kutipan per hari, satu dari tiap kelompok sumber (Al-Qur'an, hadis, nasihat
// sahabat/ulama, kata bijak, dan kalimat orisinal Nawaitu). Tiap kelompok bergeser satu butir per hari dan
// panjang daftarnya berbeda-beda, jadi kombinasi harian jarang terulang.
// Kutipan "terkenal" yang atribusinya meragukan sengaja tidak dipakai. Terjemahan ayat dan hadis berupa
// ringkasan makna; tinjau bersama ustadz sebelum dipublikasikan luas.
import type { TemaAyat } from './poster-latar';
import { isoTanggal, jamDinding } from './waktu';

export type Kutipan = {
  teks: string;
  /** Siapa yang mengucapkan, mis. "Nabi Muhammad ﷺ". Kosong = tidak ada keterangan asal yang ditampilkan. */
  penutur?: string;
  /** Asal kutipan: perawi hadis atau kitab. */
  rujukan?: string;
  jenis?: "Al-Qur'an" | 'Hadis' | 'Nasihat' | 'Hikmah';
  tema: TemaAyat;
};

/** "Penutur · rujukan" untuk poster dan teks bagikan; string kosong bila kutipan tidak punya asal. */
export const sumberKutipan = (k: Kutipan) => [k.penutur, k.rujukan].filter(Boolean).join(' · ');

export const JUMLAH_HARIAN = 5; // satu dari tiap kelompok sumber di bawah

