const quran = (teks: string, rujukan: string, tema: TemaAyat): Kutipan => ({ teks, rujukan: `QS. ${rujukan}`, jenis: "Al-Qur'an", tema });
const hadis = (teks: string, rujukan: string, tema: TemaAyat): Kutipan => ({ teks, penutur: 'Nabi Muhammad ﷺ', rujukan, jenis: 'Hadis', tema });
const nasihat = (teks: string, penutur: string, tema: TemaAyat, rujukan?: string): Kutipan => ({ teks, penutur, rujukan, jenis: 'Nasihat', tema });
const hikmah = (teks: string, penutur: string, tema: TemaAyat, rujukan?: string): Kutipan => ({ teks, penutur, rujukan, jenis: 'Hikmah', tema });

